function isSpam(email) {
    if (email.includes("FREE MONEY")) return true;
    if (email.includes("You have won")) return true;
    if (email.includes("click here now")) return true;
    return false;
}

string message = "MEET AT LUNCH";
int key = 3;
string result = "";
foreach (char letter in message)
{
    if (char.IsLetter(letter))
    {
        int position = letter - 'A';
        int newPosition = (position + key) % 26;
        result = result + (char)(newPosition + 'A');
    }
    else
    {
        result = result + letter;
    }
}
Console.WriteLine(result);
